<?php
declare(strict_types=1);
namespace Babanoell\Partners\Contract;
use Babanoell\Partners\Support\Json;use Babanoell\Partners\Support\RandomId;use PDO;use RuntimeException;use Throwable;
final class ContractRepository
{
 public function __construct(private readonly PDO $pdo){}
 public function listTemplates(string $kind=''):array{$sql='SELECT * FROM contract_templates';$p=[];if($kind!==''){$sql.=' WHERE contract_kind=:k';$p[':k']=$kind;}$sql.=' ORDER BY code,version DESC';$s=$this->pdo->prepare($sql);$s->execute($p);return $s->fetchAll(PDO::FETCH_ASSOC)?:[];}
 public function activeTemplate(string $code):?array{$s=$this->pdo->prepare("SELECT * FROM contract_templates WHERE code=:c AND status='active' ORDER BY version DESC LIMIT 1");$s->execute([':c'=>$code]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}
 public function createTemplate(string $actor,array $d):array{$version=1;$s=$this->pdo->prepare('SELECT COALESCE(MAX(version),0)+1 FROM contract_templates WHERE code=:c');$s->execute([':c'=>$d['code']]);$version=(int)$s->fetchColumn();$id=RandomId::make();$hash=hash('sha256',$d['content_html']);$this->pdo->beginTransaction();try{if($d['status']==='active'){$x=$this->pdo->prepare("UPDATE contract_templates SET status='archived',archived_at=NOW(6) WHERE code=:c AND status='active'");$x->execute([':c'=>$d['code']]);}$q=$this->pdo->prepare('INSERT INTO contract_templates(id,code,name,contract_kind,version,status,content_html,variables_json,content_hash,created_by_user_id,published_at) VALUES(:id,:c,:n,:k,:v,:s,:html,:vars,:hash,:a,:pub)');$q->execute([':id'=>$id,':c'=>$d['code'],':n'=>$d['name'],':k'=>$d['contract_kind'],':v'=>$version,':s'=>$d['status'],':html'=>$d['content_html'],':vars'=>Json::encode($d['variables']),':hash'=>$hash,':a'=>$actor,':pub'=>$d['status']==='active'?gmdate('Y-m-d H:i:s'):null]);$this->pdo->commit();return $this->template($id)??[];}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function template(string $id):?array{$s=$this->pdo->prepare('SELECT * FROM contract_templates WHERE id=:id');$s->execute([':id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}
 public function contract(string $id):?array{$s=$this->pdo->prepare('SELECT * FROM contracts WHERE id=:id');$s->execute([':id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$this->decodeContract($r):null;}
 public function bySubject(string $type,string $id):array{$s=$this->pdo->prepare('SELECT * FROM contracts WHERE subject_type=:t AND subject_id=:id ORDER BY created_at DESC,revision DESC');$s->execute([':t'=>$type,':id'=>$id]);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];return array_map(fn($r)=>$this->decodeContract($r),$rows);}
 public function byPublicToken(string $token):?array{$h=hash('sha256',$token);$s=$this->pdo->prepare('SELECT * FROM contracts WHERE public_token_hash=:h AND public_token_expires_at>NOW(6) LIMIT 1');$s->execute([':h'=>$h]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$this->decodeContract($r):null;}
 public function createContract(string $actor,array $d):array{$id=RandomId::make();$no='CTR-'.gmdate('Ymd').'-'.strtoupper(substr($id,0,10));$s=$this->pdo->prepare('INSERT INTO contracts(id,contract_no,contract_kind,subject_type,subject_id,signer_user_id,signer_mobile,mode,status,template_id,template_code,template_version,template_hash,rendered_content,rendered_hash,artifact_status,created_by_user_id) VALUES(:id,:no,:kind,:st,:sid,:signer,:mobile,:mode,:status,:tid,:tcode,:tver,:thash,:content,:rhash,:artifact,:actor)');$s->execute([':id'=>$id,':no'=>$no,':kind'=>$d['contract_kind'],':st'=>$d['subject_type'],':sid'=>$d['subject_id'],':signer'=>$d['signer_user_id']?:null,':mobile'=>$d['signer_mobile']?:null,':mode'=>$d['mode'],':status'=>$d['status'],':tid'=>$d['template_id'],':tcode'=>$d['template_code'],':tver'=>$d['template_version'],':thash'=>$d['template_hash'],':content'=>$d['rendered_content'],':rhash'=>hash('sha256',$d['rendered_content']),':artifact'=>$d['mode']==='physical'?'not_required':'pending',':actor'=>$actor]);$this->event($id,'contract.created',$actor,'allowed',['mode'=>$d['mode'],'kind'=>$d['contract_kind']],null,null);return $this->contract($id)??[];}
 public function issuePublicToken(string $id,string $actor,int $ttl=86400):array{$token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$hash=hash('sha256',$token);$expires=gmdate('Y-m-d H:i:s',time()+max(300,$ttl));$s=$this->pdo->prepare("UPDATE contracts SET public_token_hash=:h,public_token_expires_at=:e,status=CASE WHEN status='pending' THEN 'sent' ELSE status END,row_version=row_version+1 WHERE id=:id AND status NOT IN ('cancelled','expired')");$s->execute([':h'=>$hash,':e'=>$expires,':id'=>$id]);if($s->rowCount()!==1)throw new RuntimeException('صدور لینک قرارداد ممکن نیست.');$this->event($id,'contract.link_issued',$actor,'allowed',['expires_at'=>$expires],null,null);return ['token'=>$token,'expires_at'=>$expires,'contract'=>$this->contract($id)];}
 public function markViewed(string $id,?string $ip,?string $ua):void{$s=$this->pdo->prepare("UPDATE contracts SET viewed_at=COALESCE(viewed_at,NOW(6)),status=CASE WHEN status IN ('pending','sent') THEN 'viewed' ELSE status END WHERE id=:id");$s->execute([':id'=>$id]);$this->event($id,'contract.viewed',null,'allowed',[],$ip,$ua);}
 public function latestOtp(string $contractId,bool $forUpdate=false):?array{$sql='SELECT * FROM contract_otp_challenges WHERE contract_id=:id ORDER BY created_at DESC LIMIT 1'.($forUpdate?' FOR UPDATE':'');$s=$this->pdo->prepare($sql);$s->execute([':id'=>$contractId]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?$r:null;}
 public function issueOtp(string $contractId,string $hash,int $ttl,int $cooldown,?string $ip,?string $ua):array{$this->pdo->beginTransaction();try{$c=$this->pdo->prepare('SELECT id,status,mode FROM contracts WHERE id=:id FOR UPDATE');$c->execute([':id'=>$contractId]);$contract=$c->fetch(PDO::FETCH_ASSOC);if(!is_array($contract)||$contract['mode']!=='digital'||in_array($contract['status'],['signed','cancelled','expired'],true))throw new RuntimeException('ارسال رمز برای این قرارداد مجاز نیست.');$last=$this->latestOtp($contractId,true);if(is_array($last)&&$last['status']==='active'&&strtotime((string)$last['resend_after'])>time())throw new RuntimeException('برای ارسال مجدد رمز کمی صبر کنید.');$this->pdo->prepare("UPDATE contract_otp_challenges SET status='superseded' WHERE contract_id=:id AND status='active'")->execute([':id'=>$contractId]);$id=RandomId::make();$s=$this->pdo->prepare("INSERT INTO contract_otp_challenges(id,contract_id,otp_hash,status,attempts,max_attempts,resend_after,expires_at) VALUES(:id,:c,:h,'active',0,5,:r,:e)");$s->execute([':id'=>$id,':c'=>$contractId,':h'=>$hash,':r'=>gmdate('Y-m-d H:i:s',time()+$cooldown),':e'=>gmdate('Y-m-d H:i:s',time()+$ttl)]);$this->pdo->prepare("UPDATE contracts SET status='sent',row_version=row_version+1 WHERE id=:id")->execute([':id'=>$contractId]);$this->event($contractId,'contract.otp_issued',null,'allowed',['expires_in'=>$ttl],$ip,$ua);$this->pdo->commit();return $this->latestOtp($contractId)??[];}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function verifyOtpAndSign(string $contractId,string $otp,?string $ip,?string $ua):array{$this->pdo->beginTransaction();try{$c=$this->pdo->prepare('SELECT * FROM contracts WHERE id=:id FOR UPDATE');$c->execute([':id'=>$contractId]);$contract=$c->fetch(PDO::FETCH_ASSOC);if(!is_array($contract)||$contract['mode']!=='digital')throw new RuntimeException('قرارداد دیجیتال پیدا نشد.');if($contract['status']==='signed'){$this->pdo->commit();return $this->decodeContract($contract);}if(in_array($contract['status'],['cancelled','expired'],true))throw new RuntimeException('قرارداد قابل امضا نیست.');$ch=$this->latestOtp($contractId,true);if(!is_array($ch)||$ch['status']!=='active'||strtotime((string)$ch['expires_at'])<time())throw new RuntimeException('رمز تأیید معتبر نیست یا منقضی شده است.');$attempts=(int)$ch['attempts'];$max=(int)$ch['max_attempts'];if($attempts>=$max)throw new RuntimeException('تعداد تلاش مجاز پایان یافته است.');if(!password_verify($otp,(string)$ch['otp_hash'])){$attempts++;$status=$attempts>=$max?'locked':'active';$u=$this->pdo->prepare('UPDATE contract_otp_challenges SET attempts=:a,status=:s WHERE id=:id');$u->execute([':a'=>$attempts,':s'=>$status,':id'=>$ch['id']]);$this->event($contractId,'contract.otp_failed',null,'denied',['attempts'=>$attempts],$ip,$ua);$this->pdo->commit();throw new RuntimeException('رمز تأیید صحیح نیست.');}$this->pdo->prepare("UPDATE contract_otp_challenges SET status='verified',verified_at=NOW(6) WHERE id=:id")->execute([':id'=>$ch['id']]);$this->pdo->prepare("UPDATE contracts SET status='signed',otp_verified_at=NOW(6),signed_at=NOW(6),signer_ip=:ip,signer_user_agent=:ua,row_version=row_version+1 WHERE id=:id")->execute([':ip'=>$ip,':ua'=>substr((string)$ua,0,512),':id'=>$contractId]);$this->event($contractId,'contract.signed',null,'allowed',['method'=>'otp'],$ip,$ua);$this->pdo->commit();return $this->contract($contractId)??[];}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function markPhysicalSigned(string $id,string $actor,?string $ip,?string $ua):array{$s=$this->pdo->prepare("UPDATE contracts SET status='signed',signed_at=NOW(6),signer_ip=:ip,signer_user_agent=:ua,artifact_status='pending',row_version=row_version+1 WHERE id=:id AND mode='physical' AND status NOT IN ('signed','cancelled','expired')");$s->execute([':ip'=>$ip,':ua'=>substr((string)$ua,0,512),':id'=>$id]);if($s->rowCount()!==1)throw new RuntimeException('ثبت امضای فیزیکی ممکن نیست.');$this->event($id,'contract.signed',$actor,'allowed',['method'=>'physical'],$ip,$ua);return $this->contract($id)??[];}
 public function createArtifactHandoff(string $id):array{$c=$this->contract($id);if(!is_array($c)||$c['status']!=='signed')throw new RuntimeException('قرارداد امضا شده نیست.');$artifact=$this->artifactContent($c);$sha=hash('sha256',$artifact);$token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$h=hash('sha256',$token);$this->pdo->prepare("UPDATE contract_artifact_handoffs SET status='expired' WHERE contract_id=:id AND status='active'")->execute([':id'=>$id]);$s=$this->pdo->prepare("INSERT INTO contract_artifact_handoffs(id,contract_id,token_hash,expected_sha256,status,expires_at) VALUES(:hid,:cid,:h,:sha,'active',DATE_ADD(NOW(6),INTERVAL 10 MINUTE))");$s->execute([':hid'=>RandomId::make(),':cid'=>$id,':h'=>$h,':sha'=>$sha]);return ['token'=>$token,'sha256'=>$sha,'content'=>$artifact,'filename'=>'contract-'.$c['contract_no'].'.html','mime_type'=>'text/html'];}
 public function consumeArtifactHandoff(string $id,string $token,string $sha):?array{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT * FROM contract_artifact_handoffs WHERE contract_id=:id AND token_hash=:h AND status='active' AND expires_at>NOW(6) FOR UPDATE");$s->execute([':id'=>$id,':h'=>hash('sha256',$token)]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r)||!hash_equals((string)$r['expected_sha256'],$sha)){$this->pdo->rollBack();return null;}$this->pdo->prepare("UPDATE contract_artifact_handoffs SET status='consumed',consumed_at=NOW(6) WHERE id=:id")->execute([':id'=>$r['id']]);$c=$this->contract($id);$this->pdo->commit();return is_array($c)?['contract'=>$c,'expected_sha256'=>$sha]:null;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function markArtifact(string $id,string $documentId,string $sha):void{$s=$this->pdo->prepare("UPDATE contracts SET artifact_document_id=:d,artifact_hash=:h,artifact_status='stored',row_version=row_version+1 WHERE id=:id AND status='signed'");$s->execute([':d'=>$documentId,':h'=>$sha,':id'=>$id]);$this->event($id,'contract.artifact_stored',null,'allowed',['document_id'=>$documentId,'sha256'=>$sha],null,null);}
 public function events(string $id):array{$s=$this->pdo->prepare('SELECT * FROM contract_events WHERE contract_id=:id ORDER BY created_at,id');$s->execute([':id'=>$id]);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($rows as &$r)$r['details']=Json::decodeObject($r['details_json']??null);return $rows;}
 public function event(string $id,string $type,?string $actor,string $result,array $details,?string $ip,?string $ua):void{$s=$this->pdo->prepare('INSERT INTO contract_events(id,contract_id,event_type,actor_user_id,result,details_json,ip_address,user_agent) VALUES(:id,:c,:t,:a,:r,:d,:ip,:ua)');$s->execute([':id'=>RandomId::make(),':c'=>$id,':t'=>$type,':a'=>$actor?:null,':r'=>$result,':d'=>$details!==[]?Json::encode($details):null,':ip'=>$ip,':ua'=>substr((string)$ua,0,512)]);}
 private function artifactContent(array $c):string{return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>'.htmlspecialchars((string)$c['contract_no'],ENT_QUOTES,'UTF-8').'</title><body>'.$c['rendered_content'].'<hr><p>وضعیت: امضا شده</p><p>زمان امضا: '.htmlspecialchars((string)$c['signed_at'],ENT_QUOTES,'UTF-8').'</p><p>هش محتوا: '.htmlspecialchars((string)$c['rendered_hash'],ENT_QUOTES,'UTF-8').'</p></body></html>';}
 private function decodeContract(array $r):array{return $r;}
}
